private resolveModels(input: ComparisonInput): ModelDef[] {
  let models: ModelDef[] = [];

  if (input.models && input.models.length > 0) {
    for (const modelId of input.models) {
      // In-house registry is checked FIRST — a requested id is only treated as external if it isn't an app model.
      const inHouse = APP_MODELS.find(m => m.id === modelId);
      if (inHouse) { models.push(inHouse); continue; }
      // Fall-through: accept an external id only if that provider is enabled; a disabled one is silently skipped.
      const external = EXTERNAL_MODELS.find(m => m.id === modelId);
      if (external && external.enabled) { models.push(external); continue; }
    }
  } else {
    // Default: the two standard in-house brains
    models = APP_MODELS.filter(m => ['gpt4o', 'gpt4omini'].includes(m.id));
  }

  if (input.includeExternal) {
    for (const ext of EXTERNAL_MODELS) {
      // Append benchmarks: enabled, not on-demand (pay-per-call), and not already present (dedupe guard).
      if (ext.enabled && !ext.onDemand && !models.find(m => m.id === ext.id)) {
        models.push(ext);
      }
    }
  }
  // Real guard: a comparison needs at least 2 contestants, so a typo'd id or all-disabled set fails fast.
  if (models.length < 2) {
    throw new Error('Need at least 2 models for comparison.');
  }
  return models;
}

private async evaluatePromptWithModel(
  promptId: string, prompt: string, model: ModelDef
): Promise<PromptModelResult> {
  let response: string;
  let responseTimeMs: number;

  if (model.provider === 'app') {
    // In-house client — 180s timeout: a cold model shouldn't false-fail on latency alone.
    const client = createAppClient({ model: model.id, timeout: 180000 });
    const chatResult = await client.chat(prompt);
    response = chatResult.response.answer;
    // messageResponseTime is the model's real latency, captured as a first-class metric beside the answer.
    responseTimeMs = chatResult.telemetry.messageResponseTime;
  } else if (model.provider === 'gemini') {
    // External providers: direct API helpers return the same {answer, timeMs} shape so scoring stays provider-agnostic.
    const result = await this.callGeminiDirect(prompt);
    response = result.answer; responseTimeMs = result.timeMs;
  } else if (model.provider === 'claude') {
    const result = await this.callClaudeDirect(prompt);
    response = result.answer; responseTimeMs = result.timeMs;
  }
  // ... scoring happens next (see evaluateRubricDimensions)
  return { promptId, model: model.id, response, responseTimeMs /* , ... */ } as PromptModelResult;
}

private async evaluateRubricDimensions(prompt: string, response: string) {
  // JSON-mode by instruction: the judge is told to respond with ONLY a JSON object so the reply is parseable.
  const judgePrompt = `You are an evaluation judge. Score the following AI
response on these 6 dimensions using a scale of 1-10.

USER PROMPT: ${prompt}
AI RESPONSE: ${response}

1. accuracy  2. completeness  3. clarity_structure
4. handling_ambiguity  5. hallucination_resistance  6. formatting_fidelity

Respond ONLY with a JSON object, no other text.`;

  // A cheap, fixed judge model (gpt4omini) scores every answer — the SAME judge keeps scores comparable across models.
  const judgeClient = createAppClient({ model: 'gpt4omini' });
  const judgeAnswer = (await judgeClient.chat(judgePrompt)).response.answer;
  // Extract the first {...} block — defends against a judge that wraps its JSON in prose (flat object only, no nesting).
  const rawScores = JSON.parse(judgeAnswer.match(/\{[^}]+\}/)[0]);

  const dimensionScores = dimensions.map(dim => {
    // Clamp to 1-10 and default any missing dimension to 5 (neutral) — a partial judge reply degrades, never crashes.
    const rawScore = Math.min(10, Math.max(1, rawScores[dim] || 5));
    const normalizedScore = Math.round((rawScore / 10) * 1000) / 1000;
    // Per-dimension PASS gate at 0.70; averageNormalized (below) is the aggregate the ranking actually sorts on.
    return { dimension: dim, rawScore, normalizedScore, passed: normalizedScore >= 0.70 };
  });
  const averageNormalized = /* mean of the 6 normalizedScore values */ 0;
  return { dimensions: dimensionScores, averageNormalized };
}

private buildModelSummaries(models: ModelDef[], results: PromptModelResult[]): ModelSummary[] {
  return models.map(model => {
    // !r.error is load-bearing: errored responses are dropped from every average, not counted as zeros.
    const modelResults = results.filter(r => r.model === model.id && !r.error);
    const passCount = modelResults.filter(r => r.verdict === 'PASS').length;
    const total = modelResults.length;

    // total>0 guards divide-by-zero when every prompt for this model errored out.
    const avgAggregate = total > 0
      ? Math.round((modelResults.reduce((s, r) => s + r.aggregateScore, 0) / total) * 1000) / 1000
      : 0;
    const avgResponseTimeMs = total > 0
      ? Math.round(modelResults.reduce((s, r) => s + r.responseTimeMs, 0) / total)
      : 0;

    // passRate is a display string (e.g. "82%"); the ranking sorts on avgAggregate (a number), not this.
    return { model: model.id, provider: model.provider, totalPrompts: total,
             passCount, avgAggregate, avgResponseTimeMs,
             passRate: total > 0 ? `${Math.round((passCount / total) * 100)}%` : '0%' };
  });
}

private buildRecommendation(sorted: ModelSummary[]): string {
  // sorted is already ranked by avgAggregate desc: [0] is the best model, the last entry is the worst.
  const best = sorted[0];
  const worst = sorted[sorted.length - 1];

  let rec = `Winner: ${best.model} (${best.provider}) with aggregate score ` +
    `${best.avgAggregate.toFixed(3)} and ${best.passRate} pass rate.`;

  if (sorted.length > 1) {
    // Bucket the top-to-bottom gap: a rubric aggregate is noisy, so a tiny lead isn't a real difference.
    const gap = best.avgAggregate - worst.avgAggregate;
    if (gap < 0.05) rec += ' Models perform similarly — choose based on latency and cost.';
    else if (gap < 0.15) rec += ' Moderate performance difference — consider the trade-off.';
    else rec += ' Significant performance gap — strongly recommend the top model.';
  }

  // Re-sort a COPY by latency; if the fastest model isn't the winner, surface the quality-vs-speed trade-off.
  const fastest = [...sorted].sort((a, b) => a.avgResponseTimeMs - b.avgResponseTimeMs)[0];
  if (fastest.model !== best.model) rec += ` Fastest: ${fastest.model} (${fastest.avgResponseTimeMs}ms avg).`;
  return rec;
}
